// ════════════════════════════════════════════════════════════════
// Glossaire statique FR → DE (mode « Deutsch »).
//
// Même rôle que UI_GLOSSARY (glossary.js) pour l'anglais et UI_GLOSSARY_ES
// (glossaryEs.js) pour l'espagnol : le vocabulaire d'interface le plus fréquent
// bascule instantanément, hors ligne et sans appel IA. Le reste (recettes,
// étapes, notes…) part à l'IA puis au cache.
//
// MÊMES CLÉS que UI_GLOSSARY, dans le même ordre : toute entrée ajoutée au
// glossaire anglais doit l'être ici aussi. `npm run lint:glossary` le vérifie.
//
// Registre : allemand de Suisse (Schweizer Hochdeutsch) de cuisine et
// d'hôtellerie professionnelles. Jamais de ß (ss), vouvoiement (Sie), actions
// à l'infinitif (« Speichern »), guillemets « » sans espace. Vocabulaire métier
// aligné sur la tâche `translate` d'ai-proxy : carte → Karte, fiche technique →
// Rezeptblatt, perte → Verlust, pointage → Zeiterfassung (pointer → stempeln),
// établissement → Betrieb, réservation → Reservation, planning → Dienstplan,
// inventaire → Inventur, TVA → MWST, CCNT → L-GAV, fiduciaire → Treuhand.
// « Carte » reste Karte (le menu), et au paiement « Carte bancaire » devient
// Bankkarte, « Cartes bancaires » Bankkarten.
// ════════════════════════════════════════════════════════════════

