  "Ajouter une heure de relevé": "Messzeit hinzufügen",
  "Les heures de relevé ne sont pas les mêmes d'une maison à l'autre : un seul service qui démarre à 6h ne se relève pas comme un double service midi et soir. Réglez ici les heures de l'établissement : la carte de l'accueil HACCP dit à l'équipe quand relever, et le tableau de bord signale un relevé en retard. Un relevé en dehors de ces heures reste toujours possible.": "Die Messzeiten sind nicht in jedem Haus gleich: Ein einzelner Service, der um 6 Uhr beginnt, wird nicht gleich gemessen wie ein doppelter Service mittags und abends. Stellen Sie hier die Zeiten des Betriebs ein: Die Karte auf der HACCP-Startseite sagt dem Team, wann gemessen wird, und das Dashboard meldet eine verspätete Messung. Eine Messung ausserhalb dieser Zeiten bleibt immer möglich.",
