  "« Estimé » : un ingrédient de la fiche n'est pas lié au catalogue, son prix vient du produit de même nom dans l'inventaire (prix des factures) ou au catalogue de l'établissement, à défaut du prix figé sur la fiche.": "«Geschätzt»: Eine Zutat des Rezeptblatts ist nicht mit dem Katalog verknüpft, ihr Preis stammt vom gleichnamigen Produkt in der Inventur (Rechnungspreise) oder aus dem Katalog des Betriebs, ersatzweise vom im Rezeptblatt festgehaltenen Preis.",
  "Les préparations maison (pickles, fonds, confits, desserts) sont liées à leur fiche recette : leur prix est le coût matière de la fiche, au kilo ou à la portion selon l'unité de comptage.": "Die hausgemachten Zubereitungen (Pickles, Fonds, Confits, Desserts) sind mit ihrem Rezeptblatt verknüpft: Ihr Preis entspricht dem Warenaufwand des Rezeptblatts, pro Kilo oder pro Portion je nach Zähleinheit.",
