  "Dossier de caisse téléchargé ; des jours non clôturés sont restés dehors, voir lisez-moi.txt.": "Kassendossier heruntergeladen; nicht abgeschlossene Tage blieben aussen vor, siehe lisez-moi.txt.",
  "Dossier de caisse téléchargé.": "Kassendossier heruntergeladen.",
  // Caisse v9 : terminal de paiement relié.
  "Terminal de paiement": "Zahlungsterminal",
  "Au tap sur « Carte », la caisse envoie le montant au terminal ; le client paie sur le terminal ; la caisse reçoit « accepté » ou « refusé » et pose le paiement toute seule.": "Beim Tippen auf «Karte» sendet die Kasse den Betrag ans Terminal; der Gast bezahlt am Terminal; die Kasse erhält «akzeptiert» oder «abgelehnt» und erfasst die Zahlung selbst.",
  "La caisse ne voit jamais une carte : ni numéro, ni date, ni code. Elle garde seulement le résultat (marque, quatre derniers chiffres, code d'autorisation). L'argent va du prestataire à la maison, sans passer par l'app.": "Die Kasse sieht nie eine Karte: weder Nummer noch Datum noch Code. Sie behält nur das Ergebnis (Marke, letzte vier Ziffern, Autorisierungscode). Das Geld geht vom Anbieter direkt an das Haus, ohne über die App zu laufen.",
  "Terminaux reliés": "Verbundene Terminals",
  "Les terminaux n'ont pas pu être lus. Fermez les Réglages et rouvrez-les.": "Die Terminals konnten nicht gelesen werden. Schliessen Sie die Einstellungen und öffnen Sie sie wieder.",
  "Aucun terminal relié : les cartes s'encaissent à la main, comme aujourd'hui.": "Kein Terminal verbunden: Karten werden wie bisher von Hand kassiert.",
  "Terminal simulé": "Simuliertes Terminal",
  "n° de série": "Seriennummer",
  "Clé enregistrée, se termine par": "Schlüssel gespeichert, endet auf",
  "Clé enregistrée": "Schlüssel gespeichert",
  "Relié le": "Verbunden am",
  "Il ne sert que les tickets du mode test : aucun argent ne bouge, aucun vrai ticket ne peut être payé par lui.": "Es dient nur den Bons im Testmodus: Kein Geld bewegt sich, kein echter Bon kann damit bezahlt werden.",
  "Ce terminal a déjà encaissé un paiement réel accepté.": "Dieses Terminal hat bereits eine echte, akzeptierte Zahlung kassiert.",
  "Ce terminal n'a pas encore encaissé de paiement réel accepté : faites un premier paiement de 1 franc avant le service.": "Dieses Terminal hat noch keine echte, akzeptierte Zahlung kassiert: Machen Sie vor dem Service eine erste Zahlung von 1 Franken.",
  "Garder": "Behalten",
  "Retirer ce terminal": "Dieses Terminal entfernen",
  "Terminaux retirés :": "Entfernte Terminals:",
  "Leurs paiements passés restent dans la caisse ; un remboursement se fait alors chez le prestataire.": "Ihre vergangenen Zahlungen bleiben in der Kasse; eine Rückerstattung erfolgt dann beim Anbieter.",
  "Relier un terminal": "Terminal verbinden",
  "Prestataire": "Anbieter",
  "Clé": "Schlüssel",
  "Jumelage": "Kopplung",
  "Aucun prestataire réel n'est encore proposé. Le terminal simulé sert à s'entraîner en mode test ; un vrai terminal sera ajouté quand son prestataire aura confirmé ses règles et fourni un moyen d'essai sans argent réel.": "Noch wird kein echter Anbieter angeboten. Das simulierte Terminal dient zum Üben im Testmodus; ein echtes Terminal wird hinzugefügt, sobald sein Anbieter seine Regeln bestätigt und eine Testmöglichkeit ohne echtes Geld bereitgestellt hat.",
  "Nom du terminal, tel que l'équipe le verra": "Name des Terminals, wie das Team ihn sehen wird",
  "Terminal du bar": "Terminal an der Bar",
  "Numéro de série, lu sous le terminal": "Seriennummer, unter dem Terminal abgelesen",
  "Saisie masquée": "Verdeckte Eingabe",
  "La clé part une seule fois vers le serveur, qui la range dans son coffre. Elle ne revient jamais à l'écran : seuls ses quatre derniers caractères seront rappelés.": "Der Schlüssel geht ein einziges Mal an den Server, der ihn in seinem Tresor ablegt. Er erscheint nie wieder am Bildschirm: Nur seine letzten vier Zeichen werden angezeigt.",
  "Code de jumelage": "Kopplungscode",
  "Code lu sur le terminal": "Am Terminal abgelesener Code",
  "Le code s'affiche sur le terminal et ne sert qu'une fois : il prouve que le terminal est devant vous.": "Der Code erscheint am Terminal und gilt nur einmal: Er beweist, dass das Terminal vor Ihnen steht.",
  "Relier ce terminal": "Dieses Terminal verbinden",
  "Relier ou retirer un terminal : consultant ou patron de la maison.": "Ein Terminal verbinden oder entfernen: Berater oder Inhaber des Hauses.",
  "Plafond d'un paiement sur le terminal, en CHF": "Obergrenze einer Zahlung am Terminal, in CHF",
  "Au-dessus de ce montant, pourboire compris, la caisse n'envoie rien au terminal : une erreur de saisie ne part pas en débit.": "Über diesem Betrag, Trinkgeld inbegriffen, sendet die Kasse nichts ans Terminal: Ein Eingabefehler führt nicht zu einer Belastung.",
  "Terminal relié": "Terminal verbunden",
  "Terminal retiré": "Terminal entfernt",
  "Étapes pour relier un terminal": "Schritte zum Verbinden eines Terminals",
  "Aucun appareil, aucun argent : pour s'entraîner en mode test.": "Kein Gerät, kein Geld: zum Üben im Testmodus.",
  "Clé d'essai": "Testschlüssel",
  "Huit caractères au moins. Ce que vous voulez : ce terminal ne parle à personne.": "Mindestens acht Zeichen. Was Sie wollen: Dieses Terminal spricht mit niemandem.",
  "Six lettres ou chiffres, par exemple ESSAI1.": "Sechs Buchstaben oder Ziffern, zum Beispiel TEST01.",
  "Paiement par carte": "Kartenzahlung",
  "Paiement par carte sur le terminal": "Kartenzahlung am Terminal",
  "Terminal :": "Terminal:",
  "Mode test : terminal simulé, aucun argent ne bouge.": "Testmodus: simuliertes Terminal, kein Geld bewegt sich.",
  "À payer sur le terminal": "Am Terminal zu bezahlen",
  "Dont pourboire, à part du total :": "Davon Trinkgeld, separat vom Total:",
  "La demande n'est peut-être pas partie. « Réessayer » renvoie la même demande : le client ne peut pas être débité deux fois.": "Die Anfrage ist vielleicht nicht rausgegangen. «Erneut versuchen» sendet dieselbe Anfrage erneut: Der Gast kann nicht zweimal belastet werden.",
  "Présentez la carte sur le terminal": "Halten Sie die Karte ans Terminal",
  "Envoi du montant au terminal...": "Betrag wird ans Terminal gesendet...",
  "Le terminal attend la carte. La caisse reçoit la réponse toute seule.": "Das Terminal wartet auf die Karte. Die Kasse erhält die Antwort selbst.",
  "Revenir aux moyens de paiement": "Zurück zu den Zahlungsmitteln",
  "Paiement accepté": "Zahlung akzeptiert",
  "Paiement refusé": "Zahlung abgelehnt",
  "Paiement annulé": "Zahlung abgebrochen",
  "Délai dépassé sur le terminal": "Zeitüberschreitung am Terminal",
  "Rien n'a été posé sur le ticket.": "Auf dem Bon wurde nichts erfasst.",
  "Regardez le terminal": "Schauen Sie aufs Terminal",
  "La caisse n'a pas reçu la réponse du terminal. Rien n'est posé sur le ticket, et aucune nouvelle demande ne part tant que ce paiement n'est pas éclairci.": "Die Kasse hat die Antwort des Terminals nicht erhalten. Auf dem Bon wird nichts erfasst, und keine neue Anfrage geht raus, solange diese Zahlung nicht geklärt ist.",
  "Redemander le statut": "Status erneut abfragen",
  "Le terminal reste muet : trancher": "Das Terminal bleibt stumm: entscheiden",
  "Lisez le reçu ou l'écran du terminal. Votre choix et son motif sont écrits au Journal d'activité.": "Lesen Sie den Beleg oder den Bildschirm des Terminals. Ihre Wahl und deren Grund werden im Aktivitätsprotokoll festgehalten.",
  "Motif, par exemple : reçu du terminal vu": "Grund, zum Beispiel: Beleg des Terminals gesehen",
  "Le terminal n'a rien débité": "Das Terminal hat nichts belastet",
  "Le terminal a accepté": "Das Terminal hat akzeptiert",
  "Si le terminal reste muet, appelez un responsable : lui seul peut dire si le paiement est passé.": "Bleibt das Terminal stumm, rufen Sie eine verantwortliche Person: Nur sie kann sagen, ob die Zahlung durchgegangen ist.",
