  "Les paiements par carte de ce ticket n'ont pas pu être lus. Encaisser sans les relire pourrait oublier une carte déjà acceptée.": "Die Kartenzahlungen dieses Bons konnten nicht gelesen werden. Ohne sie erneut zu lesen zu kassieren, könnte eine bereits akzeptierte Karte vergessen.",
  "Un paiement par carte attend d'être éclairci : regardez le terminal.": "Eine Kartenzahlung muss geklärt werden: Schauen Sie aufs Terminal.",
