  "Ventes encaissées moins annulations, TVA comprise, au jour d'exploitation. Les tickets de test ne comptent pas.": "Kassierte Verkäufe minus Stornierungen, inkl. MWST, am Betriebstag. Testbons zählen nicht.",
  "Le chiffre d'affaires de la caisse moins la TVA de chaque ticket.": "Der Umsatz der Kasse minus die MWST jedes Bons.",
  "Somme de la TVA de chaque ticket, arrondie au centime par ticket et par taux.": "Summe der MWST jedes Bons, pro Bon und pro Satz auf den Rappen gerundet.",
  "Nombre de tickets numérotés encaissés ; un ticket annulé depuis reste compté le jour de sa vente.": "Anzahl kassierter nummerierter Bons; ein seither stornierter Bon bleibt am Tag seines Verkaufs gezählt.",
  "Nombre d'annulations, comptées le jour où elles sont faites.": "Anzahl Stornierungen, gezählt am Tag, an dem sie erfolgen.",
  "Couverts saisis sur les tickets encaissés, moins ceux des tickets annulés.": "Auf den kassierten Bons erfasste Gedecke, minus jene der stornierten Bons.",
  "Chiffre d'affaires TVA comprise divisé par les tickets, annulations déduites ; recalculé sur chaque pas.": "Umsatz inkl. MWST geteilt durch die Bons, Stornierungen abgezogen; für jedes Intervall neu berechnet.",
  "Chiffre d'affaires TVA comprise divisé par les couverts ; recalculé sur chaque pas.": "Umsatz inkl. MWST geteilt durch die Gedecke; für jedes Intervall neu berechnet.",
  "Ce que la maison garde par moyen de paiement : montants et arrondis des espèces, annulations déduites, pourboires à part.": "Was das Haus pro Zahlungsmittel behält: Beträge und Bargeldrundungen, Stornierungen abgezogen, Trinkgelder separat.",
  "Pourboires saisis à l'encaissement, hors chiffre d'affaires.": "Beim Kassieren erfasste Trinkgelder, ausserhalb des Umsatzes.",
  "Écart entre les espèces comptées et les espèces attendues, à la dernière clôture de chaque jour.": "Differenz zwischen gezähltem und erwartetem Bargeld beim letzten Abschluss jedes Tages.",
  "Quantités vendues, annulations déduites, offerts compris.": "Verkaufte Mengen, Stornierungen abgezogen, Offerten inbegriffen.",
  "Somme des lignes vendues, TVA comprise : elle fait le chiffre d'affaires de la période.": "Summe der verkauften Zeilen, inkl. MWST: Sie ergibt den Umsatz des Zeitraums.",
  "Montant des remises accordées sur les tickets encaissés.": "Betrag der auf kassierten Bons gewährten Rabatte.",
  "Valeur au prix d'origine des lignes offertes.": "Wert der offerierten Zeilen zum ursprünglichen Preis.",
  "De l'ouverture du ticket à son encaissement, sur les ventes servies à table ; recalculée sur chaque pas.": "Von der Eröffnung des Bons bis zum Kassieren, bei am Tisch servierten Verkäufen; für jedes Intervall neu berechnet.",
  "Couverts des réservations honorées, non pointées et prévues ; ni les annulées ni les no-show.": "Gedecke der wahrgenommenen, nicht erfassten und erwarteten Reservationen; weder stornierte noch No-Shows.",
  "Réservations valides, annulées exclues. Une table est une réservation, pas une table de la salle.": "Gültige Reservationen, stornierte ausgenommen. Ein Tisch ist eine Reservation, nicht ein Tisch im Saal.",
  "Réservations marquées no-show.": "Als No-Show markierte Reservationen.",
  "No-show divisés par les réservations échues ; recalculé sur chaque pas.": "No-Shows geteilt durch die fälligen Reservationen; für jedes Intervall neu berechnet.",
  "Réservations annulées divisées par toutes les réservations ; recalculé sur chaque pas.": "Stornierte Reservationen geteilt durch alle Reservationen; für jedes Intervall neu berechnet.",
  "Réservations passées restées sans arrivée ni no-show, divisées par les réservations échues.": "Vergangene Reservationen ohne Ankunft und ohne No-Show, geteilt durch die fälligen Reservationen.",
  "Couverts divisés par la capacité des services ouverts, d'après les réglages de la réservation en ligne.": "Gedecke geteilt durch die Kapazität der offenen Services, gemäss den Einstellungen der Online-Reservation.",
  "Couverts divisés par les réservations comptées ; recalculé sur chaque pas.": "Gedecke geteilt durch die gezählten Reservationen; für jedes Intervall neu berechnet.",
  "Couverts divisés par les jours ouverts du pas ; sans réglages, par les jours qui ont une réservation.": "Gedecke geteilt durch die offenen Tage des Intervalls; ohne Einstellungen durch die Tage mit einer Reservation.",
  "Montant des factures d'achat non exclues : total hors TVA, à défaut TVA comprise, à défaut somme des lignes lues. Jour de la date de facture.": "Betrag der nicht ausgeschlossenen Einkaufsrechnungen: Total exkl. MWST, ersatzweise inkl. MWST, ersatzweise Summe der gelesenen Zeilen. Tag des Rechnungsdatums.",
  "Nombre de factures d'achat qui portent un montant ; les bons de livraison et de commande ne comptent pas.": "Anzahl Einkaufsrechnungen mit Betrag; Liefer- und Bestellscheine zählen nicht.",
  "Chiffre du jour saisi ou clôturé par la caisse, à défaut ventes de la caisse reliée, plus les notes de séjour d'un hôtel.": "Von der Kasse erfasster oder abgeschlossener Tagesumsatz, ersatzweise Verkäufe der verbundenen Kasse, plus die Gästerechnungen eines Hotels.",
  "Ventes moins la TVA, calculée sur le total de chaque taux : la somme des points peut s'écarter du total de quelques centimes.": "Verkäufe minus MWST, berechnet auf dem Total jedes Satzes: Die Summe der Punkte kann um einige Rappen vom Total abweichen.",
  "Achats hors TVA de la période, par date de facture, avec la règle des Analyses des dépenses.": "Einkäufe exkl. MWST des Zeitraums, nach Rechnungsdatum, mit der Regel der Ausgabenanalysen.",
  "Coût matière divisé par le chiffre d'affaires hors TVA ; recalculé sur chaque pas.": "Warenaufwand geteilt durch den Umsatz exkl. MWST; für jedes Intervall neu berechnet.",
  "Chiffre d'affaires hors TVA moins le coût matière, recalculée sur chaque pas ; n/a pour un pas sans vente ou sans facture chiffrée.": "Umsatz exkl. MWST minus Warenaufwand, für jedes Intervall neu berechnet; n/a für ein Intervall ohne Verkauf oder ohne Rechnung mit Betrag.",
  "Charges fixes saisies, au prorata des jours du pas.": "Erfasste Fixkosten, anteilig nach den Tagen des Intervalls.",
  "Estimation depuis les heures pointées, les salaires saisis et les charges sociales. Réservé à la direction.": "Schätzung aus den gestempelten Stunden, den erfassten Löhnen und den Sozialabgaben. Der Leitung vorbehalten.",
  "Coût du personnel estimé divisé par le chiffre d'affaires hors TVA. Réservé à la direction.": "Geschätzter Personalaufwand geteilt durch den Umsatz exkl. MWST. Der Leitung vorbehalten.",
  "Marge brute moins les charges fixes et, pour la direction, le coût du personnel estimé ; recalculé sur chaque pas, n/a quand la marge l'est.": "Bruttomarge minus Fixkosten und, für die Leitung, minus geschätzter Personalaufwand; für jedes Intervall neu berechnet, n/a wenn die Marge n/a ist.",
