  "Réservations arrivées par la réservation en ligne, au jour du service demandé, quel que soit leur sort.": "Über die Online-Reservation eingegangene Reservationen, am Tag des gewünschten Service, unabhängig von ihrem Ausgang.",
  "Demandes en ligne confirmées, arrivées, parties ou en no-show.": "Online-Anfragen bestätigt, angekommen, gegangen oder No-Show.",
