  "Réservations non annulées dont la date de prise est connue ; par délai, combien de jours avant le service elles ont été prises.": "Nicht stornierte Reservationen mit bekanntem Erfassungsdatum; nach Vorlauf, wie viele Tage vor dem Service sie erfasst wurden.",
  "Jours entre la prise de la réservation et le service, en moyenne ; une saisie après coup compte zéro. Recalculé sur chaque pas.": "Tage zwischen der Erfassung der Reservation und dem Service, im Durchschnitt; eine nachträgliche Erfassung zählt null. Für jedes Intervall neu berechnet.",
  "La moitié des réservations sont prises moins de jours avant le service, l'autre moitié plus. Recalculé sur chaque pas.": "Die Hälfte der Reservationen wird weniger Tage vor dem Service erfasst, die andere Hälfte mehr. Für jedes Intervall neu berechnet.",
  "Réservations comptées marquées comme groupe.": "Als Gruppe markierte gezählte Reservationen.",
  "Réservations comptées placées sur au moins une table du plan de salle, divisées par les réservations comptées.": "Gezählte Reservationen, die auf mindestens einem Tisch des Tischplans platziert sind, geteilt durch die gezählten Reservationen.",
  "Réservations comptées reliées à une fiche client, divisées par les réservations comptées.": "Mit einer Kundenkarte verknüpfte gezählte Reservationen, geteilt durch die gezählten Reservationen.",
  "Fiches clients différentes parmi les réservations comptées ; recalculé sur chaque pas, un client présent sur deux pas compte dans chacun.": "Verschiedene Kundenkarten unter den gezählten Reservationen; für jedes Intervall neu berechnet, ein Kunde in zwei Intervallen zählt in jedem.",
  "Fiches clients avec au moins une réservation honorée ; recalculé sur chaque pas.": "Kundenkarten mit mindestens einer wahrgenommenen Reservation; für jedes Intervall neu berechnet.",
  "Fiches clients avec au moins deux réservations honorées dans le pas ; recalculé sur chaque pas.": "Kundenkarten mit mindestens zwei wahrgenommenen Reservationen im Intervall; für jedes Intervall neu berechnet.",
  "Clients revenus divisés par les clients venus ; recalculé sur chaque pas.": "Wiederkehrende Kunden geteilt durch die gekommenen Kunden; für jedes Intervall neu berechnet.",
  "Réservations comptées venues avec un passeport gourmand.": "Gezählte Reservationen, die mit einem Passeport gourmand kamen.",
  "Réservations comptées qui portent au moins un tag du type choisi (occasion, allergène, régime).": "Gezählte Reservationen mit mindestens einem Tag der gewählten Art (Anlass, Allergen, Ernährungsform).",
