  "TVA collectée moins impôt préalable, ou chiffre fois le taux de la dette fiscale nette, comme la Vue d'ensemble ; arrondie sur le total, la somme des points peut s'en écarter de quelques centimes.": "Erhobene MWST minus Vorsteuer, oder Umsatz mal Saldosteuersatz, wie die Übersicht; auf dem Total gerundet, kann die Summe der Punkte um einige Rappen davon abweichen.",
