  "Une valeur d'aujourd'hui ne se trace qu'avec des valeurs d'aujourd'hui des mêmes plats ou fiches.": "Ein heutiger Wert wird nur mit heutigen Werten derselben Gerichte oder Rezeptblätter gezeichnet.",
