  "Marge brute par portion": "Bruttomarge pro Portion",
  "Prix de vente TVA comprise de chaque plat de la carte choisie, celui du plat, sinon celui de son unique fiche ; « un plat de chaque » fait la somme des plats comptés.": "Verkaufspreis inkl. MWST jedes Gerichts der gewählten Karte, jener des Gerichts, sonst jener seines einzigen Rezeptblatts; «ein Gericht von jedem» ergibt die Summe der gezählten Gerichte.",
  "Coût d'une portion de chaque fiche du plat, prix du catalogue, sinon prix noté dans la fiche, comme l'écran Marges.": "Kosten einer Portion jedes Rezeptblatts des Gerichts, Preis aus dem Katalog, sonst der im Rezeptblatt notierte Preis, wie die Ansicht Margen.",
  "Coût matière divisé par le prix de vente ; pour la carte, somme des coûts sur somme des prix, un plat de chaque, sans les quantités vendues.": "Warenaufwand geteilt durch den Verkaufspreis; für die Karte Summe der Kosten durch Summe der Preise, ein Gericht von jedem, ohne die verkauften Mengen.",
  "Prix de vente moins coût matière ; n/a pour un plat sans fiche ou sans prix, qui n'entre pas dans la ligne d'ensemble.": "Verkaufspreis minus Warenaufwand; n/a für ein Gericht ohne Rezeptblatt oder ohne Preis, das nicht in die Gesamtzeile einfliesst.",
  "Prix de vente des fiches non archivées qui en ont un, comme l'onglet Fiches des Marges.": "Verkaufspreis der nicht archivierten Rezeptblätter, die einen haben, wie der Tab Rezeptblätter der Margen.",
  "Coût matière de la fiche divisé par ses portions.": "Warenaufwand des Rezeptblatts geteilt durch seine Portionen.",
  "Coût par portion divisé par le prix de vente de la fiche.": "Kosten pro Portion geteilt durch den Verkaufspreis des Rezeptblatts.",
  "Prix de vente moins coût par portion.": "Verkaufspreis minus Kosten pro Portion.",
  "Coût de tous les ingrédients de la fiche, prix du catalogue, sinon prix noté dans la fiche, comme le Chiffrage.": "Kosten aller Zutaten des Rezeptblatts, Preis aus dem Katalog, sonst der im Rezeptblatt notierte Preis, wie die Kalkulation.",
  "Coût matière divisé par les portions de la fiche.": "Warenaufwand geteilt durch die Portionen des Rezeptblatts.",
