  "Automatique choisit d'après l'écran. Ordinateur : le menu sur le côté. Tablette et Téléphone : la page d'accueil en tuiles.": "Automatisch wählt nach dem Bildschirm. Computer: das Menü an der Seite. Tablet und Telefon: die Startseite in Kacheln.",
  "Les modules avec leur nom plutôt que le rail d'icônes. Le bouton à gauche du titre et Ctrl + B font la même chose.": "Die Module mit ihrem Namen statt der Symbolleiste. Die Schaltfläche links vom Titel und Ctrl + B machen dasselbe.",
  "Glisser depuis le bord gauche de l'écran pour revenir en arrière. Automatique : seulement dans l'app installée sur iPhone et iPad, où le système n'a pas ce geste.": "Vom linken Bildschirmrand wischen, um zurückzugehen. Automatisch: nur in der auf iPhone und iPad installierten App, wo das System diese Geste nicht hat.",
