  "Chaque semaine. Ces jours-là, aucune alerte de pointage, de relevé HACCP ni de ventes n'est envoyée, et le planning les marque « Fermé ».": "Jede Woche. An diesen Tagen wird keine Warnung zu Zeiterfassung, HACCP-Messungen oder Verkäufen gesendet, und der Dienstplan markiert sie mit «Geschlossen».",
