  "Les objectifs se tracent dans Statistiques, sur le graphique de la mesure, et l'écart s'y lit en vert ou en rouge. Un champ vide : pas d'objectif.": "Die Ziele werden in den Statistiken im Diagramm der Kennzahl eingezeichnet, die Abweichung erscheint grün oder rot. Ein leeres Feld: kein Ziel.",
