  "Les réglages de la maison ne se lisent pas pour le moment. Réessayez dans un instant.": "Die Einstellungen des Hauses lassen sich im Moment nicht lesen. Versuchen Sie es gleich nochmals.",
  "Contrôler le temps de travail": "Arbeitszeit prüfen",
  "Le planning signale, sur l'horaire concerné, ce qui sort des règles ci-dessous. Il ne bloque rien. Seules les personnes qui écrivent le planning le voient.": "Der Dienstplan markiert bei der betroffenen Schicht, was von den folgenden Regeln abweicht. Er blockiert nichts. Nur wer den Dienstplan erstellt, sieht es.",
  "Repos entre deux journées": "Ruhezeit zwischen zwei Arbeitstagen",
  "La loi sur le travail demande 11 heures de suite ; elles peuvent descendre à 8 heures une fois par semaine.": "Das Arbeitsgesetz verlangt 11 zusammenhängende Stunden; einmal pro Woche dürfen es 8 Stunden sein.",
  "Pauses de la loi": "Gesetzliche Pausen",
  "15 minutes au-delà de 5 h 30 de travail, 30 minutes au-delà de 7 h, 1 heure au-delà de 9 h. La coupure d'un service coupé compte comme pause.": "15 Minuten ab 5 h 30 Arbeit, 30 Minuten ab 7 h, 1 Stunde ab 9 h. Der Unterbruch eines geteilten Dienstes zählt als Pause.",
