  "Jours sans aucun horaire, comptés sur les semaines entières affichées.": "Tage ohne jede Schicht, gezählt über die ganzen angezeigten Wochen.",
  "Aucun contrôle": "Keine Prüfung",
  "1 jour": "1 Tag",
  "2 jours": "2 Tage",
  "Ces règles changent les heures comptées : soldes, relevé CCNT, exports des salaires, Comptabilité et Statistiques. Le pointage lui-même reste affiché et gardé tel quel.": "Diese Regeln ändern die gezählten Stunden: Saldi, L-GAV-Auszug, Lohnexporte, Buchhaltung und Statistiken. Die Zeiterfassung selbst bleibt unverändert angezeigt und gespeichert.",
  "Arrivée en avance": "Frühe Ankunft",
  "Quand quelqu'un pointe avant l'heure prévue. Un retard compte toujours dès le pointage.": "Wenn jemand vor der geplanten Zeit einstempelt. Eine Verspätung zählt immer ab dem Einstempeln.",
