  "Comptée dès l'heure prévue": "Ab der geplanten Zeit gezählt",
  "Arrondi": "Rundung",
  "Arrivée et départ arrondis au plus proche, vers le haut comme vers le bas : juste pour chacun sur le mois.": "Ankunft und Weggang auf den nächsten Wert gerundet, nach oben wie nach unten: über den Monat für alle gerecht.",
