  // Dossier du contrôle (HACCP) et conformité CCNT du planning, 18.11.2026.
  "Dossier du contrôle": "Kontrolldossier",
  "Le PDF à remettre à l'inspecteur du contrôle des denrées.": "Das PDF, das Sie der Lebensmittelkontrolle übergeben.",
  "Du": "Vom",
  "Au": "Bis",
  "Par défaut, les": "Standardmässig die letzten",
  "derniers jours. Sur cette période :": "Tage. In diesem Zeitraum:",
  "contrôles": "Kontrollen",
  "contrôle": "Kontrolle",
  "Le dossier reprend les relevés, les contrôles, les actions correctives, les problèmes signalés, les photos de traçabilité et les durées de vie des étiquettes. Sa dernière page liste ce que vous devez fournir à côté.": "Das Dossier umfasst die Messungen, die Kontrollen, die Korrekturmassnahmen, die gemeldeten Probleme, die Rückverfolgbarkeitsfotos und die Haltbarkeiten der Etiketten. Die letzte Seite listet auf, was Sie zusätzlich vorlegen müssen.",
  "Préparation du dossier…": "Dossier wird vorbereitet…",
  "Choisissez une date de début et une date de fin.": "Wählen Sie ein Start- und ein Enddatum.",
  "La date de début doit venir avant la date de fin.": "Das Startdatum muss vor dem Enddatum liegen.",
  "La période commence après aujourd'hui.": "Der Zeitraum beginnt nach heute.",
  "Le dossier du contrôle est téléchargé.": "Das Kontrolldossier wurde heruntergeladen.",
  "Le dossier n'a pas pu être préparé.": "Das Dossier konnte nicht vorbereitet werden.",
  "Repos court": "Kurze Ruhezeit",
  "Jours d'affilée": "Tage am Stück",
  "Amplitude": "Tagesspanne",
  "Conformité CCNT": "L-GAV-Konformität",
  "infraction": "Verstoss",
  "infractions": "Verstösse",
  "point d'attention": "Hinweis",
  "points d'attention": "Hinweise",
  "Règles de la CCNT": "Regeln des L-GAV",
  "Revenir sans enregistrer": "Zurück ohne Speichern",
  "Enregistrer quand même": "Trotzdem speichern",
  "Autres points :": "Weitere Punkte:",
  "Aucun point à signaler sur la période affichée.": "Für den angezeigten Zeitraum ist nichts zu melden.",
  "Repos entre deux journées": "Ruhezeit zwischen zwei Arbeitstagen",
  "Jours de travail d'affilée": "Arbeitstage am Stück",
  "Jour de repos entier": "Ganzer Ruhetag",
  "Deux jours de repos par semaine": "Zwei Ruhetage pro Woche",
  "Pauses": "Pausen",
  "Journée sur 14 heures au plus": "Arbeitstag innerhalb von höchstens 14 Stunden",
  "Durée de la semaine": "Wochenarbeitszeit",
  "Ces repères se calculent sur les horaires prévus de la période affichée : repos, jours de repos, jours d'affilée, pauses et durée de la journée.": "Diese Hinweise werden aus den geplanten Arbeitszeiten des angezeigten Zeitraums berechnet: Ruhezeit, Ruhetage, Tage am Stück, Pausen und Dauer des Arbeitstags.",
  "Cet enregistrement ne respecte pas la règle suivante. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Dieser Eintrag verstösst gegen die folgende Regel. Sie können zurückgehen und die Arbeitszeit korrigieren oder trotzdem speichern.",
  "Cet enregistrement ne respecte pas les règles suivantes. Vous pouvez revenir pour corriger l'horaire, ou enregistrer quand même.": "Dieser Eintrag verstösst gegen die folgenden Regeln. Sie können zurückgehen und die Arbeitszeit korrigieren oder trotzdem speichern.",
  "La loi demande 11 heures, ou 8 heures une fois par semaine.": "Das Gesetz verlangt 11 Stunden, oder 8 Stunden einmal pro Woche.",
  "C'est permis une fois par semaine, si la moyenne sur deux semaines atteint 11 heures.": "Das ist einmal pro Woche erlaubt, wenn der Durchschnitt über zwei Wochen 11 Stunden erreicht.",
  "Un seul repos de moins de 11 heures est permis par semaine.": "Pro Woche ist nur eine Ruhezeit unter 11 Stunden erlaubt.",
  "Septième jour d'affilée : permis si chaque journée reste sous 9 heures et si 83 heures de repos suivent.": "Siebter Tag am Stück: erlaubt, wenn jeder Arbeitstag unter 9 Stunden bleibt und 83 Stunden Ruhezeit folgen.",
  "Septième jour d'affilée : prévoyez ensuite 83 heures de repos d'affilée.": "Siebter Tag am Stück: Planen Sie danach 83 Stunden Ruhezeit am Stück ein.",
  "Septième jour d'affilée avec une journée de plus de 9 heures. Six jours au plus, sept à titre d'exception.": "Siebter Tag am Stück mit einem Arbeitstag von über 9 Stunden. Höchstens sechs Tage, ausnahmsweise sieben.",
  "Septième jour d'affilée sans 83 heures de repos à la suite. Six jours au plus, sept à titre d'exception.": "Siebter Tag am Stück ohne anschliessende 83 Stunden Ruhezeit. Höchstens sechs Tage, ausnahmsweise sieben.",
  "Plus de sept jours de travail d'affilée. Six jours au plus, sept à titre d'exception.": "Mehr als sieben Arbeitstage am Stück. Höchstens sechs Tage, ausnahmsweise sieben.",
  "Aucun jour de repos entier dans la semaine. Un jour d'au moins 24 heures est obligatoire.": "Kein ganzer Ruhetag in der Woche. Ein Tag von mindestens 24 Stunden ist obligatorisch.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 4 semaines.": "Nur ein Ruhetag in der Woche. Der zweite ist innerhalb von 4 Wochen nachzugewähren.",
  "Un seul jour de repos dans la semaine. Le second est à rendre dans les 12 semaines.": "Nur ein Ruhetag in der Woche. Der zweite ist innerhalb von 12 Wochen nachzugewähren.",
  "Pause trop courte pour la journée : 15 min au-delà de 5 h 30, 30 min au-delà de 7 h, 1 h au-delà de 9 h.": "Pause zu kurz für den Arbeitstag: 15 Min. bei mehr als 5 h 30, 30 Min. bei mehr als 7 h, 1 h bei mehr als 9 h.",
  "Un service de plus de 5 h 30 sans pause. Une pause de 15 min au moins est demandée.": "Ein Einsatz von mehr als 5 h 30 ohne Pause. Eine Pause von mindestens 15 Min. ist vorgeschrieben.",
  "La journée doit tenir dans 14 heures, pauses comprises.": "Der Arbeitstag muss innerhalb von 14 Stunden liegen, Pausen inbegriffen.",
  "Au-delà de la moyenne de la CCNT. Les heures en plus sont à compenser ou à payer.": "Über dem Durchschnitt des L-GAV. Die Mehrstunden sind zu kompensieren oder auszuzahlen.",
  // Clôture d'office des pointages oubliés (19.11.2026)
  "Clore un pointage oublié après": "Vergessenes Ausstempeln abschliessen nach",
  "Si le départ n'est pas pointé, l'horaire est clos à l'heure de fin prévue, une fois ce délai passé depuis l'arrivée. Le contrôle passe toutes les heures. Le planning affiche l'horaire comme clos d'office. Un départ pointé ensuite, ou une correction, remplace cette heure.": "Wird der Weggang nicht gestempelt, wird die Schicht zur geplanten Endzeit abgeschlossen, sobald diese Frist seit der Ankunft verstrichen ist. Die Prüfung läuft stündlich. Der Dienstplan zeigt die Schicht als automatisch abgeschlossen. Ein später gestempelter Weggang oder eine Korrektur ersetzt diese Zeit.",
  "Jamais": "Nie",
  "Départ non pointé, clos d'office": "Weggang nicht gestempelt, automatisch abgeschlossen",
  "Clos d'office": "Automatisch abgeschlossen",
  "clos d'office": "automatisch abgeschlossen",
  "8 h": "8 h",
  "10 h": "10 h",
  "12 h": "12 h",
  "14 h": "14 h",
  "16 h": "16 h",
