  "CA hors TVA : réalisé pour les jours passés, moyenne des 4 dernières semaines pour aujourd'hui et les jours à venir.": "Umsatz ohne MWST: effektiv für vergangene Tage, Durchschnitt der letzten 4 Wochen für heute und die kommenden Tage.",
