  "Moyenne des mêmes services sur les 8 dernières semaines. La prévision ne descend jamais sous les réservations déjà prises.": "Durchschnitt derselben Services der letzten 8 Wochen. Die Prognose fällt nie unter die bereits erfassten Reservationen.",
  "Pas de météo : l'adresse de l'établissement ne contient pas de NPA.": "Kein Wetter: Die Adresse des Betriebs enthält keine PLZ.",
  "Météo indisponible pour le moment : la prévision ne tient compte que des réservations.": "Wetter derzeit nicht verfügbar: Die Prognose berücksichtigt nur die Reservationen.",
  "Chargement de la météo…": "Wetter wird geladen…",
  "Pour les deux services :": "Für beide Services:",
  "effet de la météo mesuré sur vos réservations passées, appliqué à la prévision.": "Wettereffekt an Ihren vergangenen Reservationen gemessen, in der Prognose berücksichtigt.",
  "effet de la météo non mesurable : il faut au moins 8 jours de pluie ou de neige et 8 jours secs comparables. La météo s'affiche sans corriger la prévision.": "Wettereffekt nicht messbar: Es braucht mindestens 8 Tage mit Regen oder Schnee und 8 vergleichbare trockene Tage. Das Wetter wird angezeigt, ohne die Prognose zu korrigieren.",
  "effet de la météo non mesurable : vos couverts ne changent pas assez entre jours de pluie et jours secs. La météo s'affiche sans corriger la prévision.": "Wettereffekt nicht messbar: Ihre Gedeckzahlen ändern sich zwischen Regentagen und trockenen Tagen zu wenig. Das Wetter wird angezeigt, ohne die Prognose zu korrigieren.",
  "effet de la météo non mesurable : aucune station de mesure MétéoSuisse à moins de 25 km. La météo s'affiche sans corriger la prévision.": "Wettereffekt nicht messbar: keine Messstation von MeteoSchweiz im Umkreis von 25 km. Das Wetter wird angezeigt, ohne die Prognose zu korrigieren.",
