  // Mise en route d'un établissement (lots LD et A1).
  "Depuis une photo, un PDF ou le modèle Excel, rangées dans une carte": "Aus einem Foto, einem PDF oder der Excel-Vorlage, in eine Karte eingeordnet",
  "Photographiez vos fiches, ou importez-les depuis un fichier Excel ou PDF. L'app les lit, puis vous relisez avant d'enregistrer.": "Fotografieren Sie Ihre Rezeptblätter oder importieren Sie sie aus einer Excel- oder PDF-Datei. Die App liest sie, dann prüfen Sie vor dem Speichern.",
  "Importer vos fiches": "Ihre Rezeptblätter importieren",
  "étapes faites sur 5": "Schritte von 5 erledigt",
  "étape faite sur 5": "Schritt von 5 erledigt",
  "Vérifiez d'abord les informations de l'établissement.": "Prüfen Sie zuerst die Angaben zum Betrieb.",
  "Ajoutez vos fiches : une photo de chaque fiche suffit.": "Fügen Sie Ihre Rezeptblätter hinzu: Ein Foto pro Blatt genügt.",
  "Ajoutez vos produits : le modèle Excel les importe en une fois.": "Fügen Sie Ihre Produkte hinzu: Die Excel-Vorlage importiert sie auf einmal.",
  "Faites la première semaine de l'équipe.": "Erstellen Sie die erste Woche des Teams.",
  "Il ne reste qu'à terminer la mise en route.": "Es bleibt nur noch, die Einrichtung abzuschliessen.",
  "Les étapes qui rendent l'app prête pour l'équipe.": "Die Schritte, mit denen die App für das Team bereit ist.",
  "Mise en route": "Einrichtung",
  "sur 5": "von 5",
  "L'exemple est encore chargé. Effacez-le depuis la mise en route quand vos données sont là.": "Das Beispiel ist noch geladen. Löschen Sie es in der Einrichtung, sobald Ihre Daten da sind.",
  "L'établissement, les recettes, le catalogue et le planning, pour que l'équipe trouve l'app prête.": "Betrieb, Rezepte, Katalog und Dienstplan, damit das Team die App bereit vorfindet.",
  "Cinq étapes pour que l'équipe trouve l'app prête. Chacune se fait en un ou deux gestes.": "Fünf Schritte, damit das Team die App bereit vorfindet. Jeder dauert ein bis zwei Handgriffe.",
  "Chargement de la mise en route…": "Einrichtung wird geladen…",
  "La mise en route n'a pas pu être lue.": "Die Einrichtung konnte nicht geladen werden.",
  "La mise en route de cet établissement est terminée.": "Die Einrichtung dieses Betriebs ist abgeschlossen.",
  "non renseigné": "nicht angegeben",
  "Modules actifs": "Aktive Module",
  "Réglé par votre consultant.": "Von Ihrem Berater eingerichtet.",
  "C'est bon": "In Ordnung",
  "Une fiche suffit pour cocher l'étape.": "Ein Rezeptblatt genügt, um den Schritt abzuhaken.",
  "Ouvrir Cartes & Recettes": "Karten & Rezepte öffnen",
  "Un produit suffit. Dans le catalogue : Importer, puis Fichier Excel, une ligne par produit.": "Ein Produkt genügt. Im Katalog: Importieren, dann Excel-Datei, eine Zeile pro Produkt.",
  "Ouvrir le catalogue": "Katalog öffnen",
  "Le catalogue n'est pas activé pour cet établissement.": "Der Katalog ist für diesen Betrieb nicht aktiviert.",
  "Un horaire suffit. Dans le planning : Faire le planning, puis la semaine suivante.": "Ein Dienst genügt. Im Dienstplan: Dienstplan erstellen, dann die nächste Woche.",
  "Le planning n'est pas activé pour cet établissement.": "Der Dienstplan ist für diesen Betrieb nicht aktiviert.",
  "Données d'exemple": "Beispieldaten",
  "Douze recettes de bistrot, une carte et trente produits, pour voir l'app remplie. Un geste les efface, sans toucher à ce que vous avez saisi.": "Zwölf Bistro-Rezepte, eine Karte und dreissig Produkte, um die App gefüllt zu sehen. Ein Handgriff löscht sie, ohne Ihre Eingaben zu berühren.",
  "Terminer la mise en route": "Einrichtung abschliessen",
  "La carte du tableau de bord disparaît. Elle disparaît aussi d'elle-même quand les étapes 1 à 4 sont faites.": "Die Karte im Dashboard verschwindet. Sie verschwindet auch von selbst, wenn die Schritte 1 bis 4 erledigt sind.",
  "Modèle Excel des recettes": "Excel-Vorlage für Rezepte",
  "Modèle Excel du catalogue": "Excel-Vorlage für den Katalog",
  "Charger l'exemple": "Beispiel laden",
  "Effacer l'exemple": "Beispiel löschen",
  "Un instant…": "Einen Moment…",
