  "Commande par QR": "Bestellung per QR",
  "Les clients scannent le QR de l'établissement, choisissent leurs boissons et envoient la commande depuis leur téléphone. Elle arrive en caisse à valider : le bar l'accepte, ou la refuse avec un motif. Le client paie à table ou au comptoir.": "Die Gäste scannen den QR-Code des Betriebs, wählen ihre Getränke und senden die Bestellung von ihrem Telefon. Sie kommt zur Bestätigung an die Kasse: Die Bar nimmt sie an oder lehnt sie mit einem Grund ab. Der Gast bezahlt am Tisch oder an der Theke.",
