  // Lot 11 du panel : partage des pourboires (rapport de la caisse et réglages).
  'Pourboires de la période': 'Trinkgelder des Zeitraums',
  'Répartis': 'Verteilt',
  'Non répartis': 'Nicht verteilt',
  'Part du groupe': 'Anteil der Gruppe',
  'Part de chacun': 'Anteil jeder Person',
  'Hors partage': 'Nicht beteiligt',
  'pointées': 'gestempelt',
  'Les pourboires sont partagés à parts égales entre les personnes qui ont pointé sur la période.': 'Die Trinkgelder werden zu gleichen Teilen auf die Personen verteilt, die im Zeitraum gestempelt haben.',
  'Les pourboires sont partagés selon les heures pointées de chacun.': 'Die Trinkgelder werden nach den gestempelten Stunden jeder Person verteilt.',
  'Chaque groupe reçoit sa part, puis elle est partagée selon les heures pointées de chacun.': 'Jede Gruppe erhält ihren Anteil, der dann nach den gestempelten Stunden jeder Person verteilt wird.',
  'Aucune règle de partage n\'est réglée. Vous la réglez dans Réglages, Caisse, Pourboires.': 'Es ist keine Verteilregel eingestellt. Sie stellen sie unter Einstellungen, Kasse, Trinkgelder ein.',
  'La règle de partage ne correspond plus aux groupes du Planning. Vous la corrigez dans Réglages, Caisse, Pourboires.': 'Die Verteilregel passt nicht mehr zu den Gruppen des Dienstplans. Sie korrigieren sie unter Einstellungen, Kasse, Trinkgelder.',
  'Aucune heure pointée sur cette période. Le partage ne peut pas se calculer.': 'Keine gestempelten Stunden in diesem Zeitraum. Die Verteilung lässt sich nicht berechnen.',
  'Personne de ce groupe n\'a pointé sur la période. Sa part n\'est pas répartie.': 'Niemand aus dieser Gruppe hat im Zeitraum gestempelt. Ihr Anteil wird nicht verteilt.',
  'Ces personnes ont pointé sans faire partie d\'un groupe retenu par la règle. Elles ne reçoivent rien.': 'Diese Personen haben gestempelt, ohne zu einer Gruppe der Regel zu gehören. Sie erhalten nichts.',
  'Les heures pointées n\'ont pas pu être lues. Réessayez.': 'Die gestempelten Stunden konnten nicht gelesen werden. Versuchen Sie es erneut.',
  'Les groupes ou les règles de pointage n\'ont pas pu être lus. Réessayez.': 'Die Gruppen oder die Stempelregeln konnten nicht gelesen werden. Versuchen Sie es erneut.',
  'Parts égales': 'Gleiche Anteile',
  'Selon les heures': 'Nach Stunden',
  'Par groupe': 'Nach Gruppe',
  'Lecture des groupes du Planning…': 'Gruppen des Dienstplans werden gelesen…',
  'Les groupes du Planning n\'ont pas pu être lus. La règle de partage ne peut pas se régler pour le moment.': 'Die Gruppen des Dienstplans konnten nicht gelesen werden. Die Verteilregel lässt sich im Moment nicht einstellen.',
  'La règle de partage s\'appuie sur les groupes du Planning, Salle et Cuisine par exemple. Créez-les d\'abord dans Réglages, Planning, Groupes.': 'Die Verteilregel stützt sich auf die Gruppen des Dienstplans, zum Beispiel Service und Küche. Legen Sie sie zuerst unter Einstellungen, Dienstplan, Gruppen an.',
  'Les pourboires saisis à l\'encaissement sont partagés dans le rapport de la caisse, onglet Pourboires. Ils restent hors chiffre d\'affaires. Rien n\'est versé ni écrit en comptabilité.': 'Die beim Kassieren erfassten Trinkgelder werden im Kassenbericht, Reiter Trinkgelder, verteilt. Sie bleiben ausserhalb des Umsatzes. Nichts wird ausbezahlt oder verbucht.',
  'Aucune règle n\'est réglée : le rapport ne propose aucun partage.': 'Es ist keine Regel eingestellt: Der Bericht schlägt keine Verteilung vor.',
  'Comment les pourboires sont partagés': 'Wie die Trinkgelder verteilt werden',
